from decimal import Decimal, InvalidOperation
from fractions import Fraction

_CENT = Decimal("0.01")


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    # Rule 1: at most 2 decimal places is a property of the string/representation.
    # Use exponent check, not numeric quantize equality, so "10.000" is rejected.
    # This also avoids uncaught InvalidOperation from quantize on large exponents.
    try:
        if amount.as_tuple().exponent < -2:
            raise ValueError("total must have at most 2 decimal places")
    except ValueError:
        raise
    except Exception as e:
        raise ValueError("total must have at most 2 decimal places") from None
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    total_weight = sum(weights, Decimal("0"))
    if total_weight <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    cents = int(abs(amount) * 100)

    # Exact rational arithmetic to avoid Decimal rounding issues.
    # Convert each Decimal weight to an exact Fraction.
    weight_fracs = []
    for w in weights:
        # w is Decimal (or int converted to Decimal); Fraction(Decimal) is exact
        weight_fracs.append(Fraction(w))
    # Also handle int-origin weights that are exactly Decimal(int) -> Fraction still exact
    total_weight_frac = sum(weight_fracs, Fraction(0))

    floors = []
    remainders = []
    cents_frac = Fraction(cents)
    for wf in weight_fracs:
        if wf == 0:
            floors.append(0)
            remainders.append(Fraction(0))
        else:
            exact = cents_frac * wf / total_weight_frac
            fl = exact.numerator // exact.denominator
            floors.append(fl)
            remainders.append(exact - fl)

    remaining = cents - sum(floors)
    # Rule 6 & 7: only positive-weight entries participate, tie-break by larger weight then lower index
    order = sorted(
        (i for i, wf in enumerate(weight_fracs) if wf > 0),
        key=lambda i: (-remainders[i], -weight_fracs[i], i)
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts = []
    for floor_cents in floors:
        part = (Decimal(floor_cents) / Decimal(100)).quantize(_CENT)
        if negative and part != 0:
            part = -part
        parts.append(part)
    return parts
